"use client";

import { Checkbox as Primitive } from "@base-ui/react/checkbox";
import { motion } from "motion/react";
import { useId } from "react";
import type { ComponentProps, ReactNode } from "react";

import { RenderSpan } from "@/components/ui/render-element";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { motionTransition, spring } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export type CheckboxProps = Omit<
  ComponentProps<typeof Primitive.Root>,
  "className"
> & {
  className?: string;
  size?: SizeVariant;
};

export const Checkbox = ({ size, className, ...props }: CheckboxProps) => {
  const sizes = useSize(size);
  const reduced = useReducedMotion();
  return (
    <Primitive.Root
      data-slot="checkbox"
      className={cn(
        "relative inline-flex shrink-0 cursor-pointer items-center justify-center rounded border border-input outline-none transition-colors duration-(--motion-fast) focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[disabled]:pointer-events-none data-[disabled]:opacity-50 motion-reduce:transition-none",
        sizes.variant === "compact" ? "size-3.5" : "size-4",
        className
      )}
      {...props}
    >
      <Primitive.Indicator
        keepMounted
        aria-hidden="true"
        className="pointer-events-none relative flex size-full items-center justify-center"
        render={(indicatorProps, state) => (
          <span {...indicatorProps}>
            <svg
              width={sizes.icon}
              height={sizes.icon}
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
              focusable="false"
            >
              <motion.path
                d="M4 12 9 17 20 6"
                initial={false}
                animate={{
                  opacity: state.checked && !state.indeterminate ? 1 : 0,
                  pathLength: state.checked && !state.indeterminate ? 1 : 0,
                }}
                transition={motionTransition(spring.slow, reduced)}
              />
            </svg>
            <motion.span
              className="absolute h-0.5 w-2 rounded-full bg-current"
              initial={false}
              animate={{
                opacity: state.indeterminate ? 1 : 0,
                scaleX: state.indeterminate ? 1 : 0,
              }}
              transition={motionTransition(spring.moderate, reduced)}
            />
          </span>
        )}
      />
    </Primitive.Root>
  );
};

export const CheckboxItem = ({
  label,
  description,
  className,
  size: density,
  render,
  ...props
}: ComponentProps<typeof Checkbox> & {
  label: ReactNode;
  description?: ReactNode;
}) => {
  const id = useId();
  const size = useSize(density);
  const shape = useShape();
  return (
    <Checkbox
      size={density}
      data-slot="checkbox-item"
      aria-labelledby={`${id}-label`}
      aria-describedby={description ? `${id}-description` : undefined}
      className={cn(
        "relative flex w-full cursor-pointer items-center justify-start border-0 text-left outline-none transition-colors duration-(--motion-fast) data-[checked]:bg-foreground/5 data-[indeterminate]:bg-foreground/5 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 [&[data-checked]:has(+input+[data-checked])]:rounded-b-none [&[data-checked]+input+[data-checked]]:rounded-t-none",
        size.px,
        size.gap,
        size.text,
        shape,
        description ? "h-auto py-2" : size.control,
        className
      )}
      render={(checkboxProps, state) => (
        <RenderSpan
          {...checkboxProps}
          render={
            typeof render === "function"
              ? (elementProps) => render(elementProps, state)
              : render
          }
        >
          <span
            aria-hidden="true"
            className={cn(
              "flex shrink-0 items-center justify-center rounded border border-input",
              size.variant === "compact" ? "size-3.5" : "size-4"
            )}
          >
            {checkboxProps.children}
          </span>
          <span className="flex min-w-0 flex-col">
            <span id={`${id}-label`}>{label}</span>
            {description && (
              <span
                id={`${id}-description`}
                className="text-xs text-muted-foreground"
              >
                {description}
              </span>
            )}
          </span>
        </RenderSpan>
      )}
      {...props}
    />
  );
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];

import type { Transition } from "motion/react";

// Base UI owns presence; CSS consumers use the same timing ladder as Motion.
export const motionClasses = {
  moderate:
    "duration-(--motion-moderate) data-[state=closed]:duration-(--motion-exit-moderate) motion-reduce:animate-none",
  slow: "duration-(--motion-slow) data-[state=closed]:duration-(--motion-exit-slow) motion-reduce:animate-none",
};

// Fluid Functionalism's timing ladder: quick feedback, precise panels, larger moves.
export const spring = {
  fast: { bounce: 0, duration: 0.08, exit: { duration: 0.06 }, type: "spring" },
  moderate: {
    bounce: 0,
    duration: 0.16,
    exit: { duration: 0.12 },
    type: "spring",
  },
  slow: {
    bounce: 0.12,
    duration: 0.24,
    exit: { duration: 0.16 },
    type: "spring",
  },
} as const;

export const motionPresets = {
  activeIndicator: spring.moderate,
  enter: {
    animate: { opacity: 1, scale: 1 },
    initial: { opacity: 0, scale: 0.95 },
    transition: spring.moderate,
  },
  exit: { opacity: 0, scale: 0.95, transition: spring.moderate.exit },
  fade: { duration: spring.fast.duration },
  hover: spring.fast,
  layout: spring.moderate,
  snap: { duration: 0 },
} satisfies Record<string, unknown>;

export const motionTransition = (
  transition: Transition,
  reduced: boolean
): Transition =>
  reduced ? { duration: 0, opacity: motionPresets.fade } : transition;

"use client";

import { useMediaQuery } from "@/hooks/use-media-query";

/** False during SSR and the first hydration render; subscribes after mounting. */
export const useReducedMotion = () =>
  useMediaQuery("(prefers-reduced-motion: reduce)");

import { useEffect, useState } from "react";

export const useMediaQuery = (query: string) => {
  const [value, setValue] = useState(false);

  useEffect(() => {
    const onChange = (event: MediaQueryListEvent) => {
      setValue(event.matches);
    };

    const result = matchMedia(query);
    result.addEventListener("change", onChange);
    setValue(result.matches);

    return () => result.removeEventListener("change", onChange);
  }, [query]);

  return value;
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { useRender } from "@base-ui/react/use-render";

export const RenderDiv = ({
  render,
  ...props
}: useRender.ComponentProps<"div">) =>
  useRender({ defaultTagName: "div", props, render });
export const RenderSpan = ({
  render,
  ...props
}: useRender.ComponentProps<"span">) =>
  useRender({ defaultTagName: "span", props, render });
export const RenderAnchor = ({
  render,
  ...props
}: useRender.ComponentProps<"a">) =>
  useRender({ defaultTagName: "a", props, render });
